import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"存储排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/storage-issues.md","filePath":"zh/troubleshooting/storage-issues.md"}'),c={name:"zh/troubleshooting/storage-issues.md"};function s(l,e,i,r,n,u){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="存储排查" tabindex="-1">存储排查 <a class="header-anchor" href="#存储排查" aria-label="Permalink to &quot;存储排查&quot;">​</a></h1><p>按序排查、挂载拒绝路径、文件系统能力 矩阵、A/B 磁盘、以及写回缓存。</p><h2 id="按序排查" tabindex="-1">按序排查 <a class="header-anchor" href="#按序排查" aria-label="Permalink to &quot;按序排查&quot;">​</a></h2><p>运行 <code>disk-tool</code> 走菜单，或使用经典拼写：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lspci                     (PCI storage controllers present?)</span></span>
<span class="line"><span>ush&gt; ahci / ata / nvme         (family probe - the message names the fault)</span></span>
<span class="line"><span>ush&gt; dskstat                   (block instances registered? cache state)</span></span>
<span class="line"><span>ush&gt; lsblk                     (devices + partitions scanned?)</span></span>
<span class="line"><span>ush&gt; parted &lt;dev&gt;              (the partition table)</span></span>
<span class="line"><span>ush&gt; fatstat &lt;dev&gt;             (FAT statistics of a suspect volume)</span></span>
<span class="line"><span>ush&gt; fsck &lt;dev&gt;                (filesystem check - FAT32 only)</span></span>
<span class="line"><span>ush&gt; fatmount &lt;dev&gt; /mnt       (mount)</span></span>
<span class="line"><span>ush&gt; fstest                    (the VFS/fs assertion suite)</span></span></code></pre></div><h2 id="文件系统能力矩阵" tabindex="-1">文件系统能力矩阵 <a class="header-anchor" href="#文件系统能力矩阵" aria-label="Permalink to &quot;文件系统能力矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件系统</th><th>读</th><th>写</th><th>备注</th></tr></thead><tbody><tr><td>ramfs</td><td>RW</td><td>RW</td><td>rootfs；其上一切皆易失 — 只有 /etc 与已挂载卷持久</td></tr><tr><td>FAT32</td><td>RW</td><td>RW</td><td>完整写支持（文件创建、簇分配、链扩展、目录更新、删除）；在内存中缓存第一份 FAT</td></tr><tr><td>exFAT</td><td>RW</td><td>RW</td><td>不干净挂载时的脏标志警告（<code>exfat: warning - volume was not cleanly unmounted</code>）</td></tr><tr><td>ext4</td><td><strong>RO</strong></td><td>—</td><td>只读驱动；拒绝 INCOMP 特性位、&gt; 64 KiB 块大小、奇数 inode 大小</td></tr><tr><td>ext2/3</td><td>RO</td><td>—</td><td>ext2 是 ext4 的子集；ext3 日志回放不执行 — 挂载为尽力而为的 RO</td></tr></tbody></table><p>大小写敏感性跟随底层 fs（BUG-0179）：FAT32/exFAT 大小写不敏感；ramfs/ext4 大小写敏感。VFS 限制：16 个 挂载、64 个 fd、名字 64 字节、路径 256 字节。</p><h2 id="挂载拒绝路径-每个拒绝的含义" tabindex="-1">挂载拒绝路径（每个拒绝的含义） <a class="header-anchor" href="#挂载拒绝路径-每个拒绝的含义" aria-label="Permalink to &quot;挂载拒绝路径（每个拒绝的含义）&quot;">​</a></h2><ul><li><code>vfs_mount: unknown fs type</code> — 类型不是 ramfs/fat32/exfat/ext4 之一。</li><li><code>vfs_mount: parent path does not exist</code> / <code>mount point exists and is not a directory</code> — 创建挂载点（<code>mount &lt;type&gt; &lt;dev&gt; &lt;path&gt;</code> 会预先创建；<code>fatmount</code> 刻意不创建 — fatmount 失败时两行的如实消息会说明挂载点未被 创建）。</li><li><code>fat32: not a FAT32 volume (FAT12/16 detected)</code> / <code>invalid BPB</code> / <code>read boot sector failed rc=&lt;N&gt;</code> — 该卷不是可挂载的 FAT32。<code>fatstat &lt;dev&gt;</code> 显示解析的 BPB；常见原因是 设备节点错误（<code>lsblk</code>） — 或者破坏对齐的堆 回归（已修复；若你动过 mem_heap.c 请重跑 <code>ata_dma_test</code>）。</li><li><code>fat32: FAT cache alloc failed</code> / <code>FAT read failed</code> — 内存或 介质问题。</li><li><code>ext4: not an ext4 volume (bad magic)</code> / <code>read superblock failed</code> — 不是 ext4，或超级块超出驱动可达范围。</li><li><code>ext4: unsupported INCOMP feature bits 0x&lt;hex&gt; - mount refused</code>（及 块大小/inode 大小/组大小防护） — RO 驱动拒绝其 无法兑现的特性；挂载一个更简单的卷。</li><li><code>exfat: invalid number_of_fats</code> — 不是 exFAT。</li><li><code>umount: target is busy - close open files first</code> — 打开的 fd 扣住它（open_count 按节点跟踪，BUG-0061）。</li><li><code>umount: unmount nested mounts first</code> — 先子挂载（<code>mounts</code> 显示嵌套）。</li><li><code>umount: cannot unmount the root filesystem</code> — 按设计。</li><li><code>fatmount</code> 之后的 <code>mount: failed</code> — 如实的两行消息 以 <code>no FAT32 partition on device or drive not present</code> 结尾。</li></ul><h2 id="经典案例" tabindex="-1">经典案例 <a class="header-anchor" href="#经典案例" aria-label="Permalink to &quot;经典案例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>可能原因</th></tr></thead><tbody><tr><td>有效的 FAT32 卷被拒（<code>invalid BPB</code>）</td><td>设备节点错误，或破坏对齐的堆回归（已修复；若动过 mem_heap.c 重跑 <code>ata_dma_test</code>）</td></tr><tr><td>重启后写入丢失</td><td>它活在 ramfs 上 — 只有 /etc 与已挂载卷持久</td></tr><tr><td>U 盘出现后又消失</td><td>USB MSC 拔出路径 — <code>usb_hotplug_test</code> 可复现</td></tr><tr><td>对 ext2 卷做 ext4 挂载</td><td>受支持（ext2 是子集）；先检查 <code>fsck</code> 类信号 — fsck 本身仅支持 FAT32</td></tr><tr><td>向导两次询问设备名</td><td>按设计 — mkfs/abdisk/install 路径要求重输 + 裸 <code>y</code> 确认</td></tr><tr><td><code>abdisk</code> 之后 A/B 磁盘&quot;absent&quot;</td><td>重跑 <code>update status</code>；向导循环复查直到服务看到它</td></tr><tr><td>干净卸载后 fsck 报脏</td><td>FSINFO/FAT 镜像回归 — 报告它；这类是 bug</td></tr><tr><td><code>blk: write to protected device ... REFUSED (ocire recovery disk)</code></td><td>整盘 OCIRE 保护 — 按设计；仅从 OCIRE <code>repair</code> 修改该卷</td></tr><tr><td><code>blkcache: alloc FAILED - cache disabled (raw I/O)</code></td><td>64 槽缓存无法分配；系统继续无缓存（更慢但正确）</td></tr><tr><td><code>virtio-blk: write rejected (device is read-only)</code></td><td>QEMU 驱动器以 <code>readonly=on</code> 挂载 — 按设计</td></tr><tr><td>AHCI 端口上的 ATAPI 设备</td><td><code>&lt;port&gt;: ATAPI (not supported)</code> — 已声明的限制</td></tr></tbody></table><h2 id="a-b-磁盘-—-布局与修复" tabindex="-1">A/B 磁盘 — 布局与修复 <a class="header-anchor" href="#a-b-磁盘-—-布局与修复" aria-label="Permalink to &quot;A/B 磁盘 — 布局与修复&quot;">​</a></h2><p>由 <code>abdisk &lt;dev&gt;</code> 创建的布局（destructive；之后重跑 <code>ota_ab_rescan()</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p1 boot/flags 32 MB FAT32   /boot/next_B, /boot/ok_B, /boot/bootfail_B, grub.cfg</span></span>
<span class="line"><span>p2 slot A      128 MB FAT32 /boot/opencube.elf, /etc, /docs...</span></span>
<span class="line"><span>p3 slot B      128 MB FAT32 same structure as slot A</span></span>
<span class="line"><span>p4 /data       rest  FAT32 user data, downloaded packages</span></span></code></pre></div><ul><li><strong>A/B 磁盘缺失</strong>是第 3 号 OTA 静默失败：<code>update status</code> 缺 <code>A/B disk: present</code>；<code>update</code> 报告 <code>update: cannot determine target slot (not booted from A/B?)</code>。</li><li><strong>修复</strong>：<code>lsblk</code> → 选设备 → <code>abdisk &lt;dev&gt;</code>（classic，或 disk-tool 向导的防护路径：它询问设备、要求你 重输确切名字、警告、并要求裸 <code>y</code>）。该链 报告自己的步骤失败（<code>abdisk: failed to write partition table</code>、<code>mkfs.fat32 failed on p&lt;N&gt;</code>、... — 第一处才是 真凶）。</li><li>回滚语义：<code>rollback</code> 清除标志；引导菜单的 <code> rollback</code> 标签意味着 <code>next_B</code> + <code>bootfail_B</code> 强制槽 A。</li><li>引导尝试预算：<code>/boot/grub/grubenv</code> 的 <code>ab_attempts</code>，上限 3。</li></ul><p>槽位选择状态机见 <a href="./boot-failures.html">boot-failures.md</a> §6。</p><h2 id="_64-槽-lru-写回缓存" tabindex="-1">64 槽 LRU 写回缓存 <a class="header-anchor" href="#_64-槽-lru-写回缓存" aria-label="Permalink to &quot;64 槽 LRU 写回缓存&quot;">​</a></h2><p>块层维护一个 64 槽（64×512 B = 32 KiB）LRU <strong>写回</strong> 缓存：<code>{dev_idx, lba, data[512], dirty, last_used}</code>，统计 <code>{hits, misses, evicts, writebacks, used}</code>（<code>dskstat</code> 显示 图景）。</p><p>这对你意味着：</p><ul><li>写入的数据可能停留在缓存中直到逐出或刷写 — 在电源操作、你在乎的卸载、以及任何 会复位机器的实验之前运行 <code>sync</code>。</li><li><code>sync</code> 驱动 OS 缓存刷写<strong>外加</strong>逐设备刷写钩子： ATA FLUSH CACHE、NVMe Flush (0x0A)、virtio-blk FLUSH、AHCI FLUSH CACHE EXT、SCSI SYNCHRONIZE CACHE。</li><li>如果缓存无法分配（<code>blkcache: alloc FAILED - cache disabled (raw I/O)</code>），写入直通（正确，更慢）。</li></ul><h2 id="破坏性路径" tabindex="-1">破坏性路径 <a class="header-anchor" href="#破坏性路径" aria-label="Permalink to &quot;破坏性路径&quot;">​</a></h2><p><code>mkfs.*</code>、<code>abdisk</code>、<code>install</code> 摧毁数据。在向导中它们 受防护（重输设备名，然后裸 <code>y</code> — 只有 <code>y</code>/<code>Y</code> 算作 yes）；经 classic/direct 分发则立即执行 — 与历史命令一模一样 — 因此脚本保持其 语义。<strong>在 classic 形式之前对照 <code>lsblk</code> 双重核对设备名。</strong><code>fs_mount_test &lt;device&gt;</code> 也会格式化其目标。 安装器链（<code>install &lt;device&gt;</code>，≥ 64 MiB，MBR ≤ 2 TiB）与 <code>grub-install</code>（MBR 间隙 ≥ core.img 大小）逐步报告失败 — <a href="./error-catalog.html">error-catalog.md</a> §5.4。</p><h2 id="驱动级失败串" tabindex="-1">驱动级失败串 <a class="header-anchor" href="#驱动级失败串" aria-label="Permalink to &quot;驱动级失败串&quot;">​</a></h2><ul><li>AHCI：<code>ahci: issue fail (PxIS.TFE)</code>、<code>(PxTFD.ERR)</code>、 <code>ahci: issue TIMEOUT CI=...</code>、<code>&lt;port&gt;: IDENTIFY failed</code>、 <code>ahci: BAR5 invalid</code>。</li><li>ATA：<code>ata: PIO read DRQ timeout lba=&lt;n&gt;</code>、<code>atadma: xfer FAIL rc=&lt;n&gt;</code>。</li><li>NVMe：<code>nvme: BAR0 invalid</code>、<code>disable timeout ... retrying</code>、 <code>ready timeout, resetting and retrying</code>、<code>unsupported formatted LBA size (only 512B supported)</code>、<code>Identify Controller/Namespace failed</code>。</li><li>virtio-blk：<code>no legacy PCI device found (modern-only devices not supported)</code>、<code>used-ring poll timeout</code>。</li><li>USB MSC：<code>msc: CBW bulk out failed</code>、<code>msc: CSW bad signature or tag</code>、<code>usb-msc: device not ready</code>。</li></ul><p>含应对的完整清单：<a href="./error-catalog.html">error-catalog.md</a> §6.5。</p><h2 id="解读探针" tabindex="-1">解读探针 <a class="header-anchor" href="#解读探针" aria-label="Permalink to &quot;解读探针&quot;">​</a></h2><ul><li><code>dskstat</code> — 哪些块实例已注册，外加缓存 图景（64 槽 LRU 的 <code>hits/misses/evicts/writebacks/used</code>）。 零实例 = 无存储驱动绑定（见下文驱动串 / QEMU flag）。</li><li><code>lsblk</code> — 设备与扫描到的分区；设备名的权威来源 （每条破坏性命令都精确采用这些名字）。</li><li><code>parted &lt;dev&gt;</code> — MBR/GPT 表视图。</li><li><code>fatstat &lt;dev&gt;</code> — 可疑 FAT32 的解析 BPB：如果字段 （每扇区字节、每簇扇区、保留、FAT 大小、根簇） 看起来荒谬，你要么看错了设备，要么卷损坏。</li><li><code>fsck &lt;dev&gt;</code> — 仅 FAT32 的检查；判定为逐项 <code>FAIL (&lt;detail&gt;)</code> 行加最终汇总（脏簇检查打印 <code>cluster count mismatch: counted &lt;A&gt; ...</code>）。</li></ul><h2 id="qemu-存储-flag-速查" tabindex="-1">QEMU 存储 flag 速查 <a class="header-anchor" href="#qemu-存储-flag-速查" aria-label="Permalink to &quot;QEMU 存储 flag 速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>flag</th><th>备注</th></tr></thead><tbody><tr><td>普通可写磁盘</td><td><code>-drive file=hd.img,format=raw</code></td><td>显示为 IDE/ATA</td></tr><tr><td>virtio-blk 快速路径</td><td><code>-drive file=hd.img,if=virtio,format=raw</code></td><td>需要遗留 PCI 设备（modern-only 被拒）</td></tr><tr><td>AHCI</td><td><code>-device ahci</code> + <code>-drive ...</code></td><td>ATAPI 设备打印 <code>not supported</code></td></tr><tr><td>NVMe</td><td><code>-drive file=nvme.img,if=none,id=nvme0 -device nvme,drive=nvme0,serial=ns1</code></td><td>仅支持 512B LBA 大小</td></tr><tr><td>只读意图</td><td><code>readonly=on</code></td><td>写入打印如实的 <code>virtio-blk: write rejected</code></td></tr><tr><td>U 盘</td><td><code>-usb -device usb-storage,drive=u0</code></td><td>经 <code>usb_hotplug_test</code> 拔出/重接</td></tr></tbody></table><p>记住 <code>-snapshot</code>（<code>run-*</code> make 目标中的默认值）意味着 写入不持久；<code>run-bios-persist</code> / <code>run-uefi-persist</code> 关闭 它，使 <code>/etc/opencube.conf</code> 的修改落到 <code>build/etc.img</code>。</p><h2 id="分区表说明" tabindex="-1">分区表说明 <a class="header-anchor" href="#分区表说明" aria-label="Permalink to &quot;分区表说明&quot;">​</a></h2><ul><li>安装路径仅 MBR（<code>install</code> 拒绝 &gt; 2 TiB）。</li><li>GPT 仅为显示而解析（<code>parted</code>） — 系统内安装器 写入 MBR 布局。</li><li>OCIRE 恢复盘的 0xEE&quot;影子&quot; MBR 条目不带 GPT 头是刻意的伪装：常规 GPT 工具会忽略其 后的 16 MiB FAT12 卷，整盘写保护 使其保持如此。</li><li>A/B 磁盘的分区子项（p2/p3）被槽位占用 — 它们 无法注册自己的引导条目。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./error-catalog.html">error-catalog.md</a> §5.2-§5.4、§6.5 — 每条消息</li><li><a href="./../manual/filesystems.html">../manual/filesystems.md</a> — 用户指南</li><li><a href="./../manual/update-ota.html">../manual/update-ota.md</a> — A/B 的故事</li><li><a href="./boot-failures.html">boot-failures.md</a> — A/B 的引导侧</li></ul>`,35)])])}const m=t(c,[["render",s]]);export{p as __pageData,m as default};
